export function solve(input) {
  const d = input;
  let pairs = d.pairs.map((p) => [...p]);
  const out = [];
  for (const op of d.operations) {
    if (op.op === "append") pairs.push([op.key, op.value]);
    else if (op.op === "delete") pairs = pairs.filter((p) => p[0] !== op.key);
    else if (op.op === "set") {
      let seen = false;
      pairs = pairs.filter((p) => {
        if (p[0] !== op.key) return true;
        if (seen) return false;
        seen = true;
        p[1] = op.value;
        return true;
      });
      if (!seen) pairs.push([op.key, op.value]);
    } else if (op.op === "getAll") out.push(pairs.filter((p) => p[0] === op.key).map((p) => p[1]));
    else out.push(pairs.map((p) => [...p]));
  }
  return out;
}

