type Json = null | boolean | number | string | Json[] | { [key: string]: Json };
export function solve(input: Json): Json {
  const d = input as any;
  let pairs = d.pairs.map((p: string[]) => [...p]);
  const out: any[] = [];
  for (const op of d.operations) {
    if (op.op === "append") pairs.push([op.key, op.value]);
    else if (op.op === "delete") pairs = pairs.filter((p: string[]) => p[0] !== op.key);
    else if (op.op === "set") {
      let seen = false;
      pairs = pairs.filter((p: string[]) => {
        if (p[0] !== op.key) return true;
        if (seen) return false;
        seen = true;
        p[1] = op.value;
        return true;
      });
      if (!seen) pairs.push([op.key, op.value]);
    } else if (op.op === "getAll")
      out.push(pairs.filter((p: string[]) => p[0] === op.key).map((p: string[]) => p[1]));
    else out.push(pairs.map((p: string[]) => [...p]));
  }
  return out;
}
